SELECT jsonb_agg(to_jsonb(t))::text AS preflight FROM (SELECT 'Loans' AS table_name,'Ref Borrowers' AS column_name,count(*) FILTER(WHERE c."Ref Borrowers"='') AS blanks,count(*) FILTER(WHERE c."Ref Borrowers" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Borrowers",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Loans" c LEFT JOIN public."Borrowers" p ON c."Ref Borrowers"=p."Row ID" UNION ALL SELECT 'Repayments' AS table_name,'Ref Loans' AS column_name,count(*) FILTER(WHERE c."Ref Loans"='') AS blanks,count(*) FILTER(WHERE c."Ref Loans" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Loans",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Repayments" c LEFT JOIN public."Loans" p ON c."Ref Loans"=p."Row ID" UNION ALL SELECT 'Repayments' AS table_name,'Ref Charges' AS column_name,count(*) FILTER(WHERE c."Ref Charges"='') AS blanks,count(*) FILTER(WHERE c."Ref Charges" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Charges",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Repayments" c LEFT JOIN public."Charges" p ON c."Ref Charges"=p."Row ID" UNION ALL SELECT 'Repayments' AS table_name,'Ref Payment' AS column_name,count(*) FILTER(WHERE c."Ref Payment"='') AS blanks,count(*) FILTER(WHERE c."Ref Payment" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Payment",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Repayments" c LEFT JOIN public."Payments" p ON c."Ref Payment"=p."Row ID" UNION ALL SELECT 'Repayments' AS table_name,'Ref Payment Allocation' AS column_name,count(*) FILTER(WHERE c."Ref Payment Allocation"='') AS blanks,count(*) FILTER(WHERE c."Ref Payment Allocation" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Payment Allocation",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Repayments" c LEFT JOIN public."Payment Allocations" p ON c."Ref Payment Allocation"=p."Row ID" UNION ALL SELECT 'Charges' AS table_name,'Ref Loans' AS column_name,count(*) FILTER(WHERE c."Ref Loans"='') AS blanks,count(*) FILTER(WHERE c."Ref Loans" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Loans",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Charges" c LEFT JOIN public."Loans" p ON c."Ref Loans"=p."Row ID" UNION ALL SELECT 'Loan Assessment' AS table_name,'Ref Borrower' AS column_name,count(*) FILTER(WHERE c."Ref Borrower"='') AS blanks,count(*) FILTER(WHERE c."Ref Borrower" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Borrower",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Loan Assessment" c LEFT JOIN public."Borrowers" p ON c."Ref Borrower"=p."Row ID" UNION ALL SELECT 'Cash Pool Contributions' AS table_name,'Ref Partner' AS column_name,count(*) FILTER(WHERE c."Ref Partner"='') AS blanks,count(*) FILTER(WHERE c."Ref Partner" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Partner",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Cash Pool Contributions" c LEFT JOIN public."Partners" p ON c."Ref Partner"=p."Row ID" UNION ALL SELECT 'Settlements' AS table_name,'Ref Partner' AS column_name,count(*) FILTER(WHERE c."Ref Partner"='') AS blanks,count(*) FILTER(WHERE c."Ref Partner" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Partner",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Settlements" c LEFT JOIN public."Partners" p ON c."Ref Partner"=p."Row ID" UNION ALL SELECT 'Payment Allocations' AS table_name,'Ref Payment' AS column_name,count(*) FILTER(WHERE c."Ref Payment"='') AS blanks,count(*) FILTER(WHERE c."Ref Payment" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Payment",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Payment Allocations" c LEFT JOIN public."Payments" p ON c."Ref Payment"=p."Row ID" UNION ALL SELECT 'Payment Allocations' AS table_name,'Ref Charge' AS column_name,count(*) FILTER(WHERE c."Ref Charge"='') AS blanks,count(*) FILTER(WHERE c."Ref Charge" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Charge",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Payment Allocations" c LEFT JOIN public."Charges" p ON c."Ref Charge"=p."Row ID" UNION ALL SELECT 'Payments' AS table_name,'Ref Borrower' AS column_name,count(*) FILTER(WHERE c."Ref Borrower"='') AS blanks,count(*) FILTER(WHERE c."Ref Borrower" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Borrower",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Payments" c LEFT JOIN public."Borrowers" p ON c."Ref Borrower"=p."Row ID" UNION ALL SELECT 'Payments' AS table_name,'Ref Target Charge' AS column_name,count(*) FILTER(WHERE c."Ref Target Charge"='') AS blanks,count(*) FILTER(WHERE c."Ref Target Charge" IS NULL) AS nulls,count(*) FILTER(WHERE nullif(c."Ref Target Charge",'') IS NOT NULL AND p."Row ID" IS NULL) AS orphans FROM public."Payments" c LEFT JOIN public."Charges" p ON c."Ref Target Charge"=p."Row ID") t;